INSERT INTO `wp_comments` (`comment_ID`, `comment_post_ID`, `comment_author`, `comment_author_email`, `comment_author_url`, `comment_author_IP`, `comment_date`, `comment_date_gmt`, `comment_content`, `comment_karma`, `comment_approved`, `comment_agent`, `comment_type`, `comment_parent`, `user_id`) VALUES
(1, 1, 'Bir WordPress yorumcusu', 'wapuu@wordpress.example', 'https://tr.wordpress.org/', '', '2026-10-15 15:03:24', '2026-10-15 12:03:24', 'Merhaba, bu bir yorumdur.\nYorum yönetimine başlamak, düzenlemek ve silmek için lütfen Başlangıç ekranındaki yorumlar bölümüne gidin.\nYorumcuların avatarları <a href=\"https://gravatar.com/\">Gravatar</a> üzerinden alınır.', 0, 'trash', '', 'comment', 0, 0),
(2, 1, 'Ali', 'ysf.mutlu@hotmail.com', 'http://localhost/novafit', '::1', '2026-10-15 15:46:50', '2026-10-15 12:46:50', 'Çok Güzel Bir Salon Tavsiye Ederim.', 0, 'trash', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36', 'comment', 0, 1);
