(128, 1, '2026-10-25 23:38:36', '2026-10-25 20:38:36', '<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">Sınırlarını zorlamaya, gücünü kanıtlamaya ve şampiyon olmaya hazır mısın? Salonumuzun en fit üyelerini belirleyeceğimiz büyük mücadele için geri sayım başladı! Hem kendi rekorunu kırmak hem de harika ödüller kazanmak için bu heyecana ortak ol.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vivid-red\"}}}},\"textColor\":\"vivid-red\",\"fontSize\":\"medium\"} -->\n<p class=\"has-vivid-red-color has-text-color has-link-color has-medium-font-size\"><strong>Kategoriler:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item {\"fontSize\":\"medium\"} -->\n<li class=\"has-medium-font-size\"><strong>Güç Etabı:</strong> 1RM (Tekrar Maksimum) Bench Press, Squat, Deadlift</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"fontSize\":\"medium\"} -->\n<li class=\"has-medium-font-size\"><strong>Dayanıklılık Etabı:</strong> 2 Dakika Maksimum Burpee &amp; Maksimum Süre Plank</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vivid-red\"}}}},\"textColor\":\"vivid-red\",\"fontSize\":\"medium\"} -->\n<p class=\"has-vivid-red-color has-text-color has-link-color has-medium-font-size\"><strong>Ödüller:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"fontSize\":\"medium\"} -->\n<ul class=\"wp-block-list has-medium-font-size\"><!-- wp:list-item -->\n<li><strong>🥇 Birincilik:</strong> 3 Aylık Ücretsiz Üyelik + Supplement Paketi (Protein Tozu &amp; BCAA)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>🥈 <strong>İkincilik:</strong> 1 Aylık Ücretsiz Üyelik + Premium Spor Çantası</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>🥉 <strong>Üçüncülük:</strong> [Nova Fit] Özel Tasarım Shaker ve Spor Havlusu seti</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vivid-red\"}}}},\"textColor\":\"vivid-red\",\"fontSize\":\"medium\"} -->\n<p class=\"has-vivid-red-color has-text-color has-link-color has-medium-font-size\"><strong>Etkinlik Detayları:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"fontSize\":\"medium\"} -->\n<ul class=\"wp-block-list has-medium-font-size\"><!-- wp:list-item -->\n<li><strong>Tarih:</strong> 27 Aralık Pazar</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Saat:</strong> 14:00 - 18:00</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Yer:</strong> [Nova Fit] Cross Training Alanı</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Katılım Şartı:</strong> Etkinlik tüm aktif üyelerimize ücretsizdir.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\"><strong>Kayıtlar kontenjanla sınırlıdır.</strong> Hemen resepsiyona uğra, adını yazdır ve antrenmanlara başla!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vivid-red\"}}}},\"backgroundColor\":\"white\",\"textColor\":\"vivid-red\",\"fontSize\":\"medium\"} -->\n<p class=\"has-vivid-red-color has-white-background-color has-text-color has-background has-link-color has-medium-font-size\"><strong>Bahaneleri bırak, ağırlıkları kaldır! Sahnede görüşmek üzere. 💪🔥</strong></p>\n<!-- /wp:paragraph -->', '🏆 [Nova Fit] 1. Geleneksel Güç ve Dayanıklılık Turnuvası Başlıyor! 🏆', '', 'publish', 'closed', 'closed', '', '%f0%9f%8f%86-nova-fit-1-geleneksel-guc-ve-dayaniklilik-turnuvasi-basliyor-%f0%9f%8f%86', '', '', '2026-10-25 23:38:36', '2026-10-25 20:38:36', '', 0, 'http://localhost/novafit/?post_type=etkinlik&#038;p=128', 0, 'etkinlik', '', 0),
